import React, { useEffect, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { BrowserRouter, Link, Route, Routes, useLocation, useNavigate } from 'react-router-dom';
import './styles.css';
import './workflow.css';
import { supabase } from './lib/supabase';
import { DemoAIProvider, DemoOCRProvider, DemoVoiceProvider } from './providers/demo';
import AarogyaVaaniFlow from './components/AarogyaVaaniFlow';
import OpdRegistration from './components/OpdRegistration';
import LiveQueue from './components/LiveQueue';
import ConsultationsWorkspace from './components/ConsultationsWorkspace';
import PrescriptionsWorkspace from './components/PrescriptionsWorkspace';
import PharmacyWorkspace from './components/PharmacyWorkspace';
import InvestigationsWorkspace from './components/InvestigationsWorkspace';

const api = async (path: string, options: RequestInit = {}) => { const token = localStorage.getItem('niramay_token'); const body = options.body ? (() => { try { return JSON.parse(String(options.body)); } catch { return {}; } })() : {}; if (supabase && path.startsWith('/api/v1/')) { if (path === '/api/v1/dashboard') { const [opd, waiting, completed, emergency, pharmacyPending, investigationsPending] = await Promise.all([supabase.from('opd_registrations').select('id', { count: 'exact', head: true }).gte('registered_at', new Date(new Date().setHours(0, 0, 0, 0)).toISOString()), supabase.from('queue_tokens').select('id', { count: 'exact', head: true }).eq('status', 'WAITING'), supabase.from('queue_tokens').select('id', { count: 'exact', head: true }).eq('status', 'COMPLETED'), supabase.from('queue_tokens').select('id', { count: 'exact', head: true }).eq('priority', 'EMERGENCY'), supabase.from('prescriptions').select('id', { count: 'exact', head: true }).eq('status', 'PENDING'), supabase.from('investigation_orders').select('id', { count: 'exact', head: true }).neq('status', 'COMPLETED')]); const failed = [opd, waiting, completed, emergency, pharmacyPending, investigationsPending].find(result => result.error); if (failed?.error) throw failed.error; return { facility: { name: 'District Hospital, Kota' }, metrics: { opd: opd.count || 0, waiting: waiting.count || 0, completed: completed.count || 0, emergency: emergency.count || 0, pharmacyPending: pharmacyPending.count || 0, investigationsPending: investigationsPending.count || 0, followups: 0 }, demoMode: true, database: 'supabase' }; } if (path === '/api/v1/patients' && !options.method) { const query = new URLSearchParams(path.includes('?') ? path.split('?')[1] : ''); let request = supabase.from('patients').select('*').order('created_at', { ascending: false }); const q = query.get('q'); if (q) request = request.or(`name.ilike.%${q}%,niramay_id.ilike.%${q}%`); const result = await request; if (result.error) throw result.error; return { data: result.data || [], demoMode: true, database: 'supabase' }; } if (path.startsWith('/api/v1/patients/') && !path.includes('/cards')) { const id = path.split('/').pop(); const result = await supabase.from('patients').select('*,patient_contacts(*),allergies(*),medical_histories(*),consultations(*),prescriptions(*),investigation_orders(*)').or(`id.eq.${id},niramay_id.eq.${id}`).maybeSingle(); if (result.error) throw result.error; if (!result.data) throw new Error('Patient not found'); return { data: result.data, database: 'supabase' }; } if (path === '/api/v1/patients' && options.method === 'POST') { const patient = body; const result = await supabase.from('patients').insert({ niramay_id: `NIR-RJ-${new Date().getFullYear()}-${String(Date.now()).slice(-6)}`, name: patient.name, gender: patient.gender, blood_group: patient.bloodGroup, facility_id: patient.facilityId }).select().single(); if (result.error) throw result.error; return { data: result.data, demoMode: true }; } if (path === '/api/v1/queue' && !options.method) { const result = await supabase.from('queue_tokens').select('*,patients(*),departments(*)').order('created_at'); if (result.error) throw result.error; return { data: result.data || [], demoMode: true }; } if (path.startsWith('/api/v1/queue/') && options.method === 'PATCH') { const result = await supabase.from('queue_tokens').update({ status: body.status }).eq('id', path.split('/').pop()).select().single(); if (result.error) throw result.error; return { data: result.data, demoMode: true }; } if (path === '/api/v1/opd/register') { const registration = await supabase.from('opd_registrations').insert({ patient_id: body.patientId, department_id: body.departmentId }).select().single(); if (registration.error) throw registration.error; const queue = await supabase.from('queue_tokens').insert({ token: `OPD-${String(Date.now()).slice(-3)}`, patient_id: body.patientId, department_id: body.departmentId, priority: body.priority || 'ROUTINE' }).select().single(); if (queue.error) throw queue.error; return { data: { registration: registration.data, token: queue.data }, demoMode: true }; } } const response = await fetch(path, { ...options, headers: { 'Content-Type': 'application/json', ...(token ? { Authorization: `Bearer ${token}` } : {}), ...options.headers } }); const responseText = await response.text(); let responseData: any = {}; try { responseData = responseText ? JSON.parse(responseText) : {}; } catch { responseData = { error: responseText || 'Invalid server response' }; } if (!response.ok) throw new Error(responseData.error || 'Request failed'); return responseData; };
function Login() { const navigate = useNavigate(); const [error, setError] = useState(''); const submit = async (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); try { const email = String(form.get('email')); const password = String(form.get('password')); if (supabase) { const { data, error: authError } = await supabase.auth.signInWithPassword({ email, password }); if (authError) throw authError; if (data.session) localStorage.setItem('niramay_token', data.session.access_token); } else { const result = await api('/api/v1/auth/login', { method: 'POST', body: JSON.stringify({ email, password }) }); localStorage.setItem('niramay_token', result.token); } navigate('/dashboard'); } catch (e) { setError(e instanceof Error ? e.message : 'Unable to sign in'); } }; return <main className="login"><form onSubmit={submit}><div className="mark">⚕</div><p className="eyebrow">SIH PROTOTYPE / DEMO</p><h1>AAROGYAVAANI</h1><p>Digital Government Health Network</p><label>Email<input name="email" defaultValue="doctor@niramay.demo" type="email" /></label><label>Password<input name="password" defaultValue="Demo@123" type="password" /></label>{error && <div className="error">{error}</div>}<button>Sign in securely</button><small>{supabase ? 'Supabase Auth enabled' : 'Demo API mode · password Demo@123'}</small></form></main>; }
function Shell() { const [dashboard, setDashboard] = useState<any>(null); useEffect(() => { api('/api/v1/dashboard').then(setDashboard).catch(error => setDashboard({ error: error instanceof Error ? error.message : 'Unable to load dashboard' })); }, []); return <div className="shell"><aside><div className="brand"><span>⚕</span><b>AAROGYAVAANI</b><small>Digital Government Health Network</small></div><div className="facility">AUTHORIZED FACILITY<strong>District Hospital, Kota</strong><small>SIH PROTOTYPE / DEMO</small></div><nav><p>COMMAND CENTRE</p>{[['/dashboard','Dashboard'],['/patients','Patients'],['/opd/register','OPD Registration'],['/patient/intake','AarogyaVaani Intake'],['/queue','Live Queue'],['/appointments','Appointments'],['/consultations','Consultations'],['/prescriptions','Prescriptions'],['/pharmacy','Pharmacy'],['/investigations','Investigations']].map(([path, label]) => <Link key={path} to={path}>{label}</Link>)}<p>INSIGHTS</p><Link to="/analytics">Analytics</Link><Link to="/audit-logs">Audit logs</Link></nav><button className="signout" onClick={() => { localStorage.removeItem('niramay_token'); location.href='/login'; }}>Sign out</button></aside><main className="content"><header><span>District Hospital, Kota</span><span>Authorized operator session · ● Online</span></header><Routes><Route path="/dashboard" element={<Dashboard dashboard={dashboard} />} /><Route path="*" element={<Placeholder />} /></Routes></main></div>; }
function Dashboard({ dashboard }: { dashboard: any }) { if (!dashboard) return <div className="state">Loading command centre…</div>; if (dashboard.error) return <div className="state error">{dashboard.error}</div>; return <><div className="page-head"><div><p className="eyebrow">WEDNESDAY, 10 SEPTEMBER 2026 · OPD SESSION 01</p><h1>Hospital command centre</h1><p>Government Health Services, Rajasthan</p></div><span className="badge">SYSTEM ONLINE</span></div><div className="metrics">{[['TODAY’S OPD',dashboard.metrics.opd],['WAITING',dashboard.metrics.waiting],['COMPLETED',dashboard.metrics.completed],['EMERGENCY / HIGH PRIORITY',String(dashboard.metrics.emergency).padStart(2,'0')],['PHARMACY PENDING',dashboard.metrics.pharmacyPending],['INVESTIGATIONS PENDING',dashboard.metrics.investigationsPending]].map(([label,value]) => <article key={String(label)}><small>{label}</small><strong>{value}</strong><span>Connected Supabase data</span></article>)}</div><div className="grid"><section className="panel"><h2>Today's queue</h2><p>Live service activity at District Hospital, Kota.</p><div className="empty">Queue data is available through the protected API.</div></section><section className="panel"><h2>Clinical insight</h2><p>Operational planning only. No automated diagnosis is provided.</p><div className="insight">Follow-ups due this week <b>{dashboard.metrics.followups}</b></div></section></div></>; }
function Patients() { const [query, setQuery] = useState(''); const [data, setData] = useState<any[]>([]); const [state, setState] = useState('Loading patient records…'); const load = () => { setState('Loading patient records…'); api(`/api/v1/patients${query ? `?q=${encodeURIComponent(query)}` : ''}`).then(result => { setData(result.data); setState(result.data.length ? '' : 'No patient found'); }).catch(error => setState(error.message)); }; useEffect(load, []); return <div><div className="page-head"><div><p className="eyebrow">AAROGYAVAANI NATIONAL PATIENT INDEX</p><h1>Patient records</h1><p>Search authorized longitudinal records at District Hospital, Kota.</p></div><Link className="button" to="/opd/register">+ OPD registration</Link></div><section className="panel"><div className="search-row"><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Search AAROGYAVAANI ID, name or mobile"/><button className="button" onClick={load}>Search</button></div>{state && <div className="state">{state}</div>}{data.map(patient => <Link className="patient-row" to={`/patients/${patient.id}`} key={patient.id}><div><b>{patient.name}</b><small>{patient.niramayId}</small></div><span>{patient.mobile || 'Mobile not recorded'}</span><span>{patient.facility || 'District Hospital, Kota'}</span></Link>)}</section></div>; }
function PatientProfile() { const id = location.pathname.split('/').pop(); const [patient, setPatient] = useState<any>(); const [error, setError] = useState('Loading patient profile…'); useEffect(() => { api(`/api/v1/patients/${id}`).then(result => { setPatient(result.data); setError(''); }).catch(error => setError(error.message)); }, [id]); if (!patient) return <div className="state">{error}</div>; return <div><Link to="/patients">← Back to patients</Link><div className="page-head"><div><p className="eyebrow">AUTHORIZED PATIENT PROFILE</p><h1>{patient.name}</h1><p>{patient.niramayId} · {patient.gender || 'Gender not recorded'} · {patient.bloodGroup || 'Blood group not recorded'}</p></div><span className="badge">DEMO RECORD</span></div><div className="grid"><section className="panel"><h2>Identity and contact</h2><p>Facility: {patient.facility?.name || patient.facility || 'District Hospital, Kota'}</p><p>Mobile: {patient.contacts?.find((contact: any) => contact.type === 'MOBILE')?.value || patient.mobile || 'Not recorded'}</p><p>QR/card lookup uses a secure reference only; no medical history is stored in the QR.</p></section><section className="panel"><h2>Clinical timeline</h2><div className="empty">Consultations, prescriptions, investigations, and follow-ups will appear here as they are migrated.</div></section></div></div>; }
function OpdRegister() { const [patients, setPatients] = useState<any[]>([]); const [message, setMessage] = useState(''); const [patientId, setPatientId] = useState(''); const [departmentId, setDepartmentId] = useState(''); useEffect(() => { api('/api/v1/patients').then(result => { setPatients(result.data); if (result.data[0]) setPatientId(result.data[0].id); }); }, []); const submit = async () => { try { const result = await api('/api/v1/opd/register', { method: 'POST', body: JSON.stringify({ patientId, departmentId: departmentId || 'DEPT-GENERAL-MEDICINE' }) }); setMessage(`Registration complete · ${result.data.token.token}`); } catch (error) { setMessage(error instanceof Error ? error.message : 'Unable to register'); } }; return <div><div className="page-head"><div><p className="eyebrow">REGISTRATION COUNTER · DH-KOT-042</p><h1>OPD registration</h1><p>Create a visit and queue token for an authorized patient.</p></div></div><section className="panel form-card"><label>Patient<select value={patientId} onChange={event => setPatientId(event.target.value)}>{patients.map(patient => <option key={patient.id} value={patient.id}>{patient.name} · {patient.niramayId}</option>)}</select></label><label>Department<select value={departmentId} onChange={event => setDepartmentId(event.target.value)}><option value="DEPT-GENERAL-MEDICINE">General Medicine</option><option value="DEPT-EMERGENCY">Emergency</option><option value="DEPT-LABORATORY">Laboratory</option></select></label><button className="button" onClick={submit}>Register and generate token</button>{message && <div className="success">{message}</div>}</section></div>; }
function Queue() { const [data, setData] = useState<any[]>([]); const [message, setMessage] = useState('Loading live queue…'); const load = () => api('/api/v1/queue').then(result => { setData(result.data); setMessage(result.data.length ? '' : 'No active queue tokens'); }).catch(error => setMessage(error.message)); useEffect(load, []); const update = async (id: string, status: string) => { await api(`/api/v1/queue/${id}`, { method: 'PATCH', body: JSON.stringify({ status }) }); load(); }; return <div><div className="page-head"><div><p className="eyebrow">GENERAL MEDICINE · LIVE SERVICE</p><h1>Live queue</h1><p>Queue status changes persist through the protected API.</p></div></div><section className="panel">{message && <div className="state">{message}</div>}{data.map(token => <div className="queue-item" key={token.id}><b>{token.token}</b><span>{token.patient?.name}</span><span>{token.department?.name}</span><span className="badge">{token.status}</span><button onClick={() => update(token.id, 'CALLED')}>Call</button><button onClick={() => update(token.id, 'IN_CONSULTATION')}>Start</button><button onClick={() => update(token.id, 'COMPLETED')}>Complete</button></div>)}</section></div>; }
function Consultations() { const [patients, setPatients] = useState<any[]>([]); const [message, setMessage] = useState(''); useEffect(() => { api('/api/v1/patients').then(result => setPatients(result.data)); }, []); const submit = async (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); try { await api('/api/v1/consultations', { method: 'POST', body: JSON.stringify({ patientId: form.get('patientId'), doctorId: 'DOC-001', chiefComplaint: form.get('complaint'), diagnosis: form.get('diagnosis'), history: form.get('history') }) }); setMessage('Consultation saved successfully'); } catch (error) { setMessage(error instanceof Error ? error.message : 'Unable to save consultation'); } }; return <div><div className="page-head"><div><p className="eyebrow">CLINICAL RECORD</p><h1>Consultation workspace</h1><p>Document clinical assessment for an authorized patient.</p></div></div><form className="panel form-card" onSubmit={submit}><label>Patient<select name="patientId">{patients.map(patient => <option key={patient.id} value={patient.id}>{patient.name} · {patient.niramayId}</option>)}</select></label><label>Chief complaint<textarea name="complaint" /></label><label>History<textarea name="history" /></label><label>Assessment / diagnosis<textarea name="diagnosis" /></label><button className="button">Save consultation</button>{message && <div className="success">{message}</div>}</form></div>; }
function Prescriptions() { const [data, setData] = useState<any[]>([]); const [message, setMessage] = useState('Loading prescriptions…'); useEffect(() => { api('/api/v1/prescriptions').then(result => { setData(result.data); setMessage(result.data.length ? '' : 'No prescriptions found'); }).catch(error => setMessage(error.message)); }, []); return <div><div className="page-head"><div><p className="eyebrow">DIGITAL PARCHA</p><h1>Prescriptions</h1><p>Verified prescriptions enter the pharmacy queue automatically.</p></div></div><section className="panel">{message && <div className="state">{message}</div>}{data.map(rx => <div className="patient-row" key={rx.id}><div><b>{rx.patient?.name}</b><small>{rx.id}</small></div><span>{rx.items?.map((item: any) => item.medicine).join(', ')}</span><span className="badge">{rx.status}</span></div>)}</section></div>; }
function Pharmacy() { const [data, setData] = useState<any[]>([]); const [message, setMessage] = useState('Loading pharmacy queue…'); const load = () => api('/api/v1/pharmacy').then(result => { setData(result.data); setMessage(result.data.length ? '' : 'No prescriptions pending'); }).catch(error => setMessage(error.message)); useEffect(load, []); const dispense = async (id: string) => { await api(`/api/v1/pharmacy/${id}/dispense`, { method: 'POST' }); load(); }; return <div><div className="page-head"><div><p className="eyebrow">PHARMACY WORKFLOW</p><h1>Dispensing queue</h1><p>Dispensing actions are recorded against the prescription.</p></div></div><section className="panel">{message && <div className="state">{message}</div>}{data.map(rx => <div className="patient-row" key={rx.id}><div><b>{rx.patient?.name}</b><small>{rx.id}</small></div><span>{rx.items?.length || 0} medicines</span><button className="button" onClick={() => dispense(rx.id)}>Dispense</button></div>)}</section></div>; }
function Investigations() { const [data, setData] = useState<any[]>([]); const [message, setMessage] = useState('Loading investigations…'); useEffect(() => { api('/api/v1/investigations').then(result => { setData(result.data); setMessage(result.data.length ? '' : 'No investigations pending'); }).catch(error => setMessage(error.message)); }, []); return <div><div className="page-head"><div><p className="eyebrow">LABORATORY SERVICES</p><h1>Investigations</h1><p>Requested tests and verified results remain linked to the patient record.</p></div></div><section className="panel">{message && <div className="state">{message}</div>}{data.map(order => <div className="patient-row" key={order.id}><div><b>{order.investigation?.name}</b><small>{order.patient?.name}</small></div><span className="badge">{order.status}</span><span>{order.labResult?.result || 'Awaiting result'}</span></div>)}</section></div>; }
function PatientCard() { const [patient, setPatient] = useState<any>(); const [card, setCard] = useState<any>(); const [message, setMessage] = useState('Loading secure card…'); useEffect(() => { api('/api/v1/patients').then(result => { const first = result.data[0]; setPatient(first); return api('/api/v1/cards', { method: 'POST', body: JSON.stringify({ patientId: first.id }) }); }).then(result => { setCard(result.data); setMessage(''); }).catch(error => setMessage(error.message)); if (typeof window !== 'undefined') document.title = 'AAROGYAVAANI Medical Card'; }, []); if (!card || !patient) return <div className="state">{message}</div>; return <div><div className="page-head"><div><p className="eyebrow">DIGITAL MEDICAL CARD</p><h1>AAROGYAVAANI card</h1><p>SIH PROTOTYPE / DEMO · Not an officially issued government document.</p></div><button className="button" onClick={() => window.print()}>Print card</button></div><section className="medical-card"><div><p className="eyebrow">AAROGYAVAANI</p><h2>Digital Government Health Network</h2><h3>{patient.name}</h3><p>{patient.niramayId}</p><p>Blood group: {patient.bloodGroup || 'Not recorded'} · Gender: {patient.gender || 'Not recorded'}</p></div><div className="qr-box">SECURE<br/>QR<br/><small>{card.secureRef.slice(-8)}</small></div><footer>Facility: District Hospital, Kota · QR contains only a secure reference token</footer></section><section className="panel card-note"><b>Privacy boundary</b><p>The QR payload is {card.qrPayload}. It contains no medical history. Lookup requires an authenticated session and is recorded for audit.</p></section></div>; }
function Analytics() { const [data, setData] = useState<any>(); const [message, setMessage] = useState('Loading analytics…'); useEffect(() => { api('/api/v1/analytics').then(result => { setData(result.data); setMessage(''); }).catch(error => setMessage(error.message)); }, []); if (!data) return <div className="state">{message}</div>; const max = Math.max(...data.dailyOpd, 1); return <div><div className="page-head"><div><p className="eyebrow">OPERATIONAL INSIGHTS</p><h1>Hospital analytics</h1><p>Aggregated demo metrics for service planning; no unrestricted clinical records.</p></div><span className="badge">DEMO DATA</span></div><div className="metrics"><article><small>PATIENTS</small><strong>{data.patients}</strong></article><article><small>CONSULTATIONS</small><strong>{data.consultations}</strong></article><article><small>PRESCRIPTIONS</small><strong>{data.prescriptions}</strong></article></div><section className="panel chart"><h2>Daily OPD volume</h2><div className="bars">{data.dailyOpd.map((value: number, index: number) => <i key={index} style={{ height: `${Math.max(8, value / max * 100)}%` }} title={`${value} registrations`} />)}</div><div className="chart-labels">Mon Tue Wed Thu Fri Sat Sun</div></section><section className="panel"><h2>Department distribution</h2>{data.departments.map((department: any) => <div className="distribution" key={department.name}><span>{department.name}</span><b>{department.value}%</b><i><em style={{ width: `${department.value}%` }} /></i></div>)}</section></div>; }
function AuditLogs() { const [data, setData] = useState<any[]>([]); const [message, setMessage] = useState('Loading audit logs…'); useEffect(() => { api('/api/v1/audit').then(result => { setData(result.data); setMessage(result.data.length ? '' : 'No audit events recorded'); }).catch(error => setMessage(error.message)); }, []); return <div><div className="page-head"><div><p className="eyebrow">SECURITY AND ACCOUNTABILITY</p><h1>Audit logs</h1><p>Protected activity records are read-only for ordinary users.</p></div></div><section className="panel">{message && <div className="state">{message}</div>}{data.map((entry: any) => <div className="audit-row" key={entry.id}><b>{entry.action}</b><span>{entry.user?.name || 'System'}</span><span>{entry.patientRef || '—'}</span><small>{new Date(entry.createdAt).toLocaleString()}</small></div>)}</section></div>; }
function Documents() { const [file, setFile] = useState<File>(); const [message, setMessage] = useState(''); const [extraction, setExtraction] = useState<any>(); const upload = async () => { if (!file) return setMessage('Choose a document first'); if (!supabase) return setMessage('Supabase is not configured. Add your project values to .env.'); try { const path = `demo/${Date.now()}-${file.name}`; const result = await supabase.storage.from('medical-documents').upload(path, file); if (result.error) throw result.error; setExtraction(await DemoOCRProvider.extract(file.name)); setMessage('Uploaded to private storage. OCR output is unverified.'); } catch (error) { setMessage(error instanceof Error ? error.message : 'Upload failed'); } }; return <div><div className="page-head"><div><p className="eyebrow">PRIVATE MEDICAL DOCUMENTS</p><h1>Documents and OCR</h1><p>Upload to the private Supabase Storage bucket, then review demo extraction before verification.</p></div></div><section className="panel form-card"><label>Document<input type="file" accept=".pdf,.png,.jpg,.jpeg" onChange={event => setFile(event.target.files?.[0])} /></label><button className="button" onClick={upload}>Upload and extract</button>{message && <div className="success">{message}</div>}{extraction && <div className="ocr-box"><b>{extraction.status}</b><small>{extraction.provider}</small><pre>{JSON.stringify(extraction.fields, null, 2)}</pre><button className="button" onClick={() => setMessage('Human verification is required before this can become clinical information.')}>Verify after human review</button></div>}</section></div>; }
function VoiceIntake() { const [result, setResult] = useState<any>(); return <div><div className="page-head"><div><p className="eyebrow">PATIENT COMMUNICATION</p><h1>Voice intake</h1><p>Demo speech-to-text flow with human verification.</p></div></div><section className="panel form-card"><button className="button" onClick={async () => setResult(await DemoVoiceProvider.transcribe())}>Start demo voice capture</button>{result && <div className="ocr-box"><b>{result.provider}</b><p>Language detected: {result.language}</p><textarea defaultValue={result.transcript} /><button className="button" onClick={() => setResult({ ...result, verified: true })}>{result.verified ? 'Verified' : 'Save after human verification'}</button></div>}</section></div>; }
function AITriage() { const [result, setResult] = useState<any>(); const assess = (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); setResult(DemoAIProvider.assess({ symptoms: String(form.get('symptoms')), temperature: Number(form.get('temperature')), spo2: Number(form.get('spo2')) })); }; return <div><div className="page-head"><div><p className="eyebrow">DECISION SUPPORT</p><h1>AI triage</h1><p>Transparent demo/rule-based assessment for operational support.</p></div></div><form className="panel form-card" onSubmit={assess}><label>Symptoms<textarea name="symptoms" required /></label><label>Temperature °F<input name="temperature" type="number" defaultValue="98.6" step="0.1" /></label><label>SpO₂ %<input name="spo2" type="number" defaultValue="98" /></label><button className="button">Assess demo priority</button>{result && <div className="triage-result"><b>{result.level}</b>{result.indicators.map((indicator: string) => <span key={indicator}>{indicator}</span>)}<small>AI-generated decision support. Final clinical assessment must be performed by an authorized healthcare professional.</small></div>}</form></div>; }
function Followups() { const [message, setMessage] = useState(''); const submit = async (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); if (!supabase) return setMessage('Supabase is not configured. Add your project values to .env.'); const form = new FormData(event.currentTarget); const result = await supabase.from('followups').insert({ patient_id: form.get('patientId'), due_date: form.get('date'), reason: form.get('instructions'), status: 'DUE' }); setMessage(result.error ? result.error.message : 'Follow-up saved in Supabase'); }; return <div><div className="page-head"><div><p className="eyebrow">CONTINUITY OF CARE</p><h1>Follow-up scheduling</h1><p>Schedule the next visit for an existing patient.</p></div></div><form className="panel form-card" onSubmit={submit}><label>Patient ID<input name="patientId" placeholder="Supabase patient UUID" required /></label><label>Date<input name="date" type="date" required /></label><label>Instructions<textarea name="instructions" required /></label><button className="button">Save follow-up</button>{message && <div className="success">{message}</div>}</form></div>; }
function Ayush() { const [message, setMessage] = useState(''); const submit = async (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); if (!supabase) return setMessage('Supabase is not configured. Add your project values to .env.'); const form = new FormData(event.currentTarget); const result = await supabase.from('ayush_consultations').insert({ patient_id: form.get('patientId'), system: form.get('system'), treatment: form.get('treatment') }); setMessage(result.error ? result.error.message : 'AYUSH consultation saved'); }; return <div><div className="page-head"><div><p className="eyebrow">INTEGRATED CARE · DEMO</p><h1>AYUSH services</h1><p>Ayurveda, Homeopathy, Unani, and Yoga/Naturopathy records.</p></div></div><form className="panel form-card" onSubmit={submit}><label>Patient ID<input name="patientId" required /></label><label>System<select name="system"><option>Ayurveda</option><option>Homeopathy</option><option>Unani</option><option>Yoga/Naturopathy</option></select></label><label>Treatment / prescription<textarea name="treatment" required /></label><button className="button">Save AYUSH record</button>{message && <div className="success">{message}</div>}</form></div>; }
function Schemes() { const [message, setMessage] = useState(''); const submit = (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); setMessage('DEMO / MOCK result: Verification Required. No government eligibility API is connected.'); }; return <div><div className="page-head"><div><p className="eyebrow">SOCIAL PROTECTION · DEMO</p><h1>Government schemes</h1><p>Eligibility workflows are advisory and require authorized verification.</p></div></div><form className="panel form-card" onSubmit={submit}><label>Patient reference<input name="patient" required /></label><label>Scheme<select><option>Demo health assistance scheme</option><option>Demo maternal care scheme</option></select></label><button className="button">Check demo eligibility</button>{message && <div className="success">{message}</div>}</form></div>; }
function PatientPortal() { const [patient, setPatient] = useState<any>(); const [message, setMessage] = useState('Loading your portal…'); useEffect(() => { api('/api/v1/patients').then(result => { setPatient(result.data[0]); setMessage(''); }).catch(error => setMessage(error.message)); }, []); if (!patient) return <div className="state">{message}</div>; return <div><div className="page-head"><div><p className="eyebrow">PATIENT PORTAL</p><h1>Welcome, {patient.name}</h1><p>Only permitted records for this demo patient are shown.</p></div><Link className="button" to="/patient/intake">Start AarogyaVaani intake</Link><Link className="button" to="/patient/card">View digital card</Link></div><div className="grid"><section className="panel"><h2>Appointments and follow-ups</h2><div className="empty">No upcoming appointments in the demo portal.</div></section><section className="panel"><h2>Prescriptions and lab reports</h2><div className="empty">Verified records will appear here after clinical review.</div></section></div></div>; }
function PatientIntake() { const [symptoms, setSymptoms] = useState<string[]>([]); const [voice, setVoice] = useState<any>(); const [document, setDocument] = useState<any>(); const [message, setMessage] = useState(''); const commonSymptoms = ['Fever', 'Cough', 'Headache', 'Stomach pain', 'Breathing difficulty', 'Diabetes follow-up']; const toggle = (symptom: string) => setSymptoms(current => current.includes(symptom) ? current.filter(item => item !== symptom) : [...current, symptom]); const captureVoice = async () => setVoice(await DemoVoiceProvider.transcribe()); const extractDocument = async (event: React.ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; if (supabase) { const upload = await supabase.storage.from('medical-documents').upload(`patient-intake/${Date.now()}-${file.name}`, file); if (upload.error) return setMessage(upload.error.message); } setDocument(await DemoOCRProvider.extract(file.name)); }; return <div><div className="page-head"><div><p className="eyebrow">PATIENT-FACING PRE-CONSULTATION</p><h1>Prepare your health history</h1><p>Share your symptoms and old documents before entering the consultation room.</p></div><span className="badge">SIH PROTOTYPE / DEMO</span></div><div className="intake-grid"><section className="panel"><h2>1. Tell us what you feel</h2><p>Tap all symptoms that apply. You can also speak in your own language.</p><div className="symptom-grid">{commonSymptoms.map(symptom => <button className={symptoms.includes(symptom) ? 'symptom selected' : 'symptom'} key={symptom} onClick={() => toggle(symptom)}>{symptoms.includes(symptom) ? '✓ ' : ''}{symptom}</button>)}</div><button className="button" onClick={captureVoice}>🎙 Speak symptoms</button>{voice && <div className="ocr-box"><b>{voice.provider}</b><p>{voice.transcript}</p><small>Review and edit before submitting.</small></div>}</section><section className="panel"><h2>2. Add old reports</h2><p>Upload prescriptions, lab reports, discharge summaries, or medical documents.</p><input type="file" accept=".pdf,.png,.jpg,.jpeg" onChange={extractDocument} />{document && <div className="ocr-box"><b>{document.status}</b><small>{document.provider} · Human verification required</small><pre>{JSON.stringify(document.fields, null, 2)}</pre></div>}</section></div><section className="panel summary-panel"><div><p className="eyebrow">3. PHYSICIAN-READY SUMMARY PREVIEW</p><h2>Your information, structured clearly</h2><p>This summary is prepared for an authorized healthcare professional. It is not a diagnosis.</p></div><div className="summary-columns"><div><b>Selected symptoms</b><p>{symptoms.length ? symptoms.join(' · ') : 'No symptoms selected yet'}</p></div><div><b>History source</b><p>{voice ? 'Voice conversation · DEMO' : 'Touch selection'} {document ? '· Uploaded document' : ''}</p></div></div><button className="button" onClick={() => setMessage('History saved as DEMO/MOCK pre-consultation data. Human clinical verification is required.')}>Save pre-consultation history</button>{message && <div className="success">{message}</div>}</section><section className="integration-note"><b>HIS / ABDM integration</b><span>DEMO / MOCK adapter only. No live government or ABDM API is being claimed.</span></section></div>; }
function SmartPatientIntake() { const questions = [{ key: 'duration', text: 'यह समस्या कब से है?', hint: 'For example: आज से, 3 दिन से, या 2 हफ्ते से' }, { key: 'severity', text: 'तकलीफ कितनी ज्यादा है?', hint: 'हल्की, मध्यम या बहुत ज्यादा' }, { key: 'history', text: 'क्या आपको कोई पुरानी बीमारी है?', hint: 'जैसे diabetes, BP, asthma, या कोई अन्य बीमारी' }, { key: 'medicines', text: 'क्या आप अभी कोई दवा ले रहे हैं?', hint: 'दवा का नाम बताएं, नहीं तो “नहीं” लिखें' }]; const [step, setStep] = useState(0); const [symptoms, setSymptoms] = useState<string[]>([]); const [answer, setAnswer] = useState(''); const [answers, setAnswers] = useState<Record<string, string>>({}); const [summary, setSummary] = useState<any>(); const [message, setMessage] = useState(''); const [voice, setVoice] = useState(''); const toggle = (item: string) => setSymptoms(current => current.includes(item) ? current.filter(value => value !== item) : [...current, item]); const next = async () => { if (step === 0 && !symptoms.length) return setMessage('कम से कम एक symptom चुनें या बोलकर बताएं।'); if (step > 0 && !answer.trim()) return setMessage('कृपया इस सवाल का जवाब दें।'); if (step > 0) setAnswers(current => ({ ...current, [questions[step - 1].key]: answer.trim() })); setAnswer(''); setMessage(''); if (step < questions.length) return setStep(step + 1); const result = { symptoms, duration: answers.duration || answer, severity: answers.severity || 'Not provided', history: answers.history || 'Not provided', medicines: answers.medicines || 'Not provided', voice: voice || 'Touch input', disclaimer: 'AI-assisted intake only. Authorized healthcare professional must verify.' }; setStep(questions.length + 1); setSummary(result); if (supabase) { const patientResult = await supabase.from('patients').select('id').limit(1).maybeSingle(); if (patientResult.data) { const session = await supabase.from('intake_sessions').insert({ patient_id: patientResult.data.id, status: 'COMPLETED', language: 'hi-IN', completed_at: new Date().toISOString() }).select().single(); if (!session.error) { await supabase.from('clinical_summaries').insert({ session_id: session.data.id, patient_id: patientResult.data.id, summary: result }); } } } }; const speak = async () => { const result = await DemoVoiceProvider.transcribe(); setVoice(result.transcript); setMessage('Voice input captured. Please verify the transcript.'); }; return <div><div className="page-head"><div><p className="eyebrow">AAROGYAVAANI SMART INTAKE</p><h1>अपनी बीमारी बताइए</h1><p>Voice या touch से जानकारी दें। App doctor के लिए एक साफ history summary तैयार करेगा।</p></div><span className="badge">PATIENT-FACING · DEMO</span></div><section className="conversation-card"><div className="conversation-progress"><span className="progress-dot active" />{questions.map((question, index) => <span className={step > index ? 'progress-dot done' : 'progress-dot'} key={question.key} />)}</div>{step === 0 ? <><p className="assistant-bubble">आपको अभी कौन-कौन सी तकलीफ है?</p><div className="symptom-grid">{['बुखार / Fever','खांसी / Cough','सिर दर्द / Headache','पेट दर्द / Stomach pain','सांस लेने में परेशानी / Breathing difficulty','अन्य / Other'].map(item => <button className={symptoms.includes(item) ? 'symptom selected' : 'symptom'} key={item} onClick={() => toggle(item)}>{symptoms.includes(item) ? '✓ ' : ''}{item}</button>)}</div></> : step <= questions.length ? <><p className="assistant-bubble">{questions[step - 1].text}<small>{questions[step - 1].hint}</small></p><textarea className="answer-box" value={answer} onChange={event => setAnswer(event.target.value)} placeholder="अपना जवाब लिखें या बोलें..." autoFocus /></> : <div className="summary-result"><p className="eyebrow">SUMMARY READY</p><h2>Doctor-ready history तैयार है</h2><p>{summary.symptoms.join(', ')}</p><div className="summary-columns">{Object.entries(summary).filter(([key]) => !['symptoms','disclaimer'].includes(key)).map(([key, value]) => <div key={key}><b>{key}</b><p>{String(value)}</p></div>)}</div><small>{summary.disclaimer}</small></div>}<div className="conversation-actions"><button className="voice-button" onClick={speak}>🎙 बोलकर बताएं</button>{step <= questions.length && <button className="button" onClick={next}>{step === questions.length ? 'Summary बनाएं' : 'आगे बढ़ें →'}</button>}</div>{voice && <div className="voice-preview"><b>VOICE INPUT · DEMO</b><p>{voice}</p><small>कृपया verify करें—voice output अपने आप clinical fact नहीं बनता।</small></div>}{message && <div className="success">{message}</div>}</section><section className="integration-note"><b>यह diagnosis नहीं है</b><span>AI-generated intake summary है। Final assessment authorized healthcare professional करेगा। HIS/ABDM integration DEMO/MOCK है।</span></section></div>; }
function AyurvedaIntake() { const [step, setStep] = useState(0); const [answers, setAnswers] = useState<Record<string, string>>({}); const [message, setMessage] = useState(''); const sections = [{ key: 'prakriti', title: 'आपका सामान्य शरीर और स्वभाव कैसा है?', options: ['शरीर पतला, जल्दी ठंड लगती है', 'मध्यम शरीर, गर्मी अधिक लगती है', 'मजबूत शरीर, शांत और स्थिर स्वभाव'] }, { key: 'agni', title: 'आपकी भूख और पाचन कैसा है?', options: ['भूख अनियमित रहती है', 'भूख तेज लगती है', 'भूख सामान्य लेकिन पाचन धीमा है'] }, { key: 'koshta', title: 'आपका bowel pattern कैसा है?', options: ['कब्ज या अनियमित', 'ढीला या बार-बार', 'सामान्य लेकिन भारीपन'] }, { key: 'nidana', title: 'आपकी मुख्य समस्या क्या है?', options: ['दर्द / stiffness', 'पाचन / acidity', 'नींद / तनाव', 'त्वचा / allergy'] }]; const choose = async (value: string) => { const current = { ...answers, [sections[step].key]: value }; setAnswers(current); if (step < sections.length - 1) return setStep(step + 1); setStep(sections.length); if (supabase) { const patient = await supabase.from('patients').select('id').limit(1).maybeSingle(); if (patient.data) { const result = await supabase.from('ayush_consultations').insert({ patient_id: patient.data.id, system: 'Ayurveda', treatment: JSON.stringify({ type: 'Aarogyavaani intake', answers: current, status: 'PENDING_CLINICAL_REVIEW' }) }); setMessage(result.error ? result.error.message : 'Ayurveda case sheet saved securely.'); } } else setMessage('Demo case sheet तैयार है। Supabase configure होने पर यह securely save होगी।'); }; return <div><div className="page-head"><div><p className="eyebrow">AAROGYAVAANI · AYURVEDA CASE-TAKING</p><h1>अपनी Ayurvedic health story बताइए</h1><p>Touch-first, low-literacy friendly intake. यह diagnosis नहीं है—केवल consultation से पहले case preparation है।</p></div><span className="badge">DEMO / MOCK</span></div><section className="ayurveda-hero"><div><b>Aarogyavaani</b><span>AI-assisted patient case-taking for Ayurveda</span></div><small>University / SIH Prototype · No live government integration claimed</small></section><section className="panel ayurveda-step"><div className="step-count">{step < sections.length ? `Question ${step + 1} of ${sections.length}` : 'Case sheet ready'}</div>{step < sections.length ? <><h2>{sections[step].title}</h2><div className="ayurveda-options">{sections[step].options.map(option => <button key={option} onClick={() => choose(option)}>{option}</button>)}</div></> : <><p className="eyebrow">STRUCTURED SUMMARY</p><h2>आपकी Ayurvedic case sheet तैयार है</h2><div className="summary-columns">{Object.entries(answers).map(([key, value]) => <div key={key}><b>{key}</b><p>{value}</p></div>)}</div><div className="success">{message || 'Ready for authorized practitioner review.'}</div></>}<div className="ayurveda-safety">AI summary केवल draft है। Practitioner review और consent के बिना कोई treatment recommendation नहीं दी जाएगी।</div></section></div>; }
function Appointments() { const [data, setData] = useState<any[]>([]); const [message, setMessage] = useState('Loading appointments…'); const [patientId, setPatientId] = useState(''); const load = () => { if (!supabase) return setMessage('Supabase is not configured. Add your project values to .env.'); supabase.from('appointments').select('*,patients(name,niramay_id),departments(name)').order('scheduled_at').then(result => { if (result.error) setMessage(result.error.message); else { setData(result.data || []); setMessage(result.data?.length ? '' : 'No appointments scheduled'); } }); }; useEffect(load, []); const book = async () => { if (!supabase || !patientId) return setMessage('Enter a patient UUID to book an appointment'); const departments = await supabase.from('departments').select('id').limit(1).single(); if (departments.error) return setMessage(departments.error.message); const result = await supabase.from('appointments').insert({ patient_id: patientId, department_id: departments.data.id, scheduled_at: new Date(Date.now() + 86400000).toISOString(), status: 'SCHEDULED' }); setMessage(result.error ? result.error.message : 'Appointment booked in Supabase'); load(); }; return <div><div className="page-head"><div><p className="eyebrow">CARE COORDINATION</p><h1>Appointments</h1><p>Book and review visits at District Hospital, Kota.</p></div></div><section className="panel form-card"><label>Patient UUID<input value={patientId} onChange={event => setPatientId(event.target.value)} placeholder="Supabase patient UUID" /></label><button className="button" onClick={book}>Book next available appointment</button>{message && <div className="success">{message}</div>}{data.map(appointment => <div className="patient-row" key={appointment.id}><div><b>{appointment.patients?.name || 'Patient'}</b><small>{appointment.departments?.name || 'Department'}</small></div><span>{new Date(appointment.scheduled_at).toLocaleString()}</span><span className="badge">{appointment.status}</span></div>)}</section></div>; }
function SupabaseQueue() { const [items, setItems] = useState<any[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const load = async () => { if (!supabase) return setError('Supabase is not configured. Add your project values to .env.'); setLoading(true); setError(''); const result = await supabase.from('queue_tokens').select('*,patients(name,niramay_id),departments(name)').order('created_at', { ascending: true }); if (result.error) { console.error(result.error); setError(`Unable to load the queue. ${result.error.message}`); } else setItems(result.data || []); setLoading(false); }; useEffect(() => { load(); if (!supabase) return; const channel = supabase.channel('niramay-queue-live').on('postgres_changes', { event: '*', schema: 'public', table: 'queue_tokens' }, () => load()).subscribe(); return () => { supabase.removeChannel(channel); }; }, []); const update = async (id: string, status: string) => { if (!supabase) return; const result = await supabase.from('queue_tokens').update({ status }).eq('id', id); if (result.error) { console.error(result.error); setError(`Unable to update queue status. ${result.error.message}`); } else await load(); }; const callNext = () => { const next = items.find(item => item.status === 'WAITING'); if (next) update(next.id, 'CALLED'); }; return <div><div className="page-head"><div><p className="eyebrow">LIVE OPERATIONS · SUPABASE REALTIME</p><h1>Live queue</h1><p>Queue updates are persisted and refreshed through Supabase realtime.</p></div><button className="button" onClick={callNext} disabled={!items.some(item => item.status === 'WAITING')}>Call next</button></div>{error && <div className="error-panel">{error}<button onClick={load}>Retry</button></div>}{loading ? <div className="state">Loading queue…</div> : !items.length ? <div className="empty-panel"><h2>No queue tokens</h2><p>Register an OPD visit to create the first token.</p><Link className="button" to="/opd/register">Open OPD registration</Link></div> : <section className="panel queue-board"><div className="queue-now"><small>NOW SERVING</small><b>{items.find(item => item.status === 'IN_CONSULTATION')?.token || '—'}</b><span>{items.find(item => item.status === 'IN_CONSULTATION')?.patients?.name || 'No patient in consultation'}</span></div>{items.map((item, index) => <div className="queue-item" key={item.id}><b>{index + 1}</b><strong>{item.token}</strong><span>{item.patients?.name || 'Patient'}</span><span>{item.departments?.name || 'Department'}</span><span className={`status-badge ${item.status.toLowerCase()}`}>{item.status}</span><div className="queue-actions"><button onClick={() => update(item.id, 'CALLED')}>Call</button><button onClick={() => update(item.id, 'IN_CONSULTATION')}>Start</button><button onClick={() => update(item.id, 'ON_HOLD')}>Hold</button><button onClick={() => update(item.id, 'COMPLETED')}>Complete</button></div></div>)}</section>}</div>; }
function SupabaseInvestigations() { const [items, setItems] = useState<any[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const load = async () => { if (!supabase) return setError('Supabase is not configured. Add your project values to .env.'); setLoading(true); const result = await supabase.from('investigation_orders').select('*,patients(name,niramay_id),investigations(name),lab_results(result,unit,verified_at)').order('created_at', { ascending: false }); if (result.error) { console.error(result.error); setError(`Unable to load investigations. ${result.error.message}`); } else setItems(result.data || []); setLoading(false); }; useEffect(() => { load(); }, []); const update = async (id: string, status: string) => { if (!supabase) return; const result = await supabase.from('investigation_orders').update({ status }).eq('id', id); if (result.error) setError(`Unable to update investigation. ${result.error.message}`); else load(); }; return <div><div className="page-head"><div><p className="eyebrow">LABORATORY SERVICES · SUPABASE</p><h1>Investigations</h1><p>Investigation orders and status changes are stored in the connected database.</p></div></div>{error && <div className="error-panel">{error}<button onClick={load}>Retry</button></div>}{loading ? <div className="state">Loading investigations…</div> : !items.length ? <div className="empty-panel"><h2>No investigations found</h2><p>New investigation orders will appear here.</p></div> : <section className="panel"><div className="investigation-head"><span>Patient</span><span>Investigation</span><span>Status</span><span>Result</span><span>Actions</span></div>{items.map(item => <div className="investigation-row" key={item.id}><div><b>{item.patients?.name || 'Patient'}</b><small>{item.patients?.niramay_id}</small></div><span>{item.investigations?.name || 'Investigation'}</span><span className={`status-badge ${item.status.toLowerCase()}`}>{item.status}</span><span>{item.lab_results?.[0]?.result || 'Pending verification'}</span><div><button onClick={() => update(item.id, 'IN_PROGRESS')}>Process</button><button onClick={() => update(item.id, 'COMPLETED')}>Complete</button><button onClick={() => update(item.id, 'VERIFIED')}>Verify</button></div></div>)}</section>}</div>; }
function Placeholder() { return <div className="state"><p className="eyebrow">AAROGYAVAANI WORKSPACE</p><h1>Module ready for migration</h1><p>This route is scaffolded in the new React application. Existing working workflows remain available in the legacy demo.</p></div>; }
function App() { if (location.pathname === '/login') return <Login />; if (!localStorage.getItem('niramay_token')) return <Login />; if (location.pathname === '/patients') return <Patients />; if (location.pathname.startsWith('/patients/')) return <PatientProfile />; if (location.pathname === '/opd/register') return <OpdRegistration />; if (location.pathname === '/queue') return <LiveQueue />; if (location.pathname === '/consultations') return <ConsultationsWorkspace />; if (location.pathname === '/prescriptions') return <PrescriptionsWorkspace />; if (location.pathname === '/pharmacy') return <PharmacyWorkspace />; if (location.pathname === '/investigations') return <InvestigationsWorkspace />; if (location.pathname === '/patient/intake' || location.pathname === '/patient/aarogyavaani') return <AarogyaVaaniFlow />; if (location.pathname === '/patient/ayurveda-intake') return <AyurvedaIntake />; if (location.pathname === '/patient/card') return <PatientCard />; if (location.pathname === '/patient') return <PatientPortal />; if (location.pathname === '/appointments') return <Appointments />; if (location.pathname === '/analytics') return <Analytics />; if (location.pathname === '/audit-logs') return <AuditLogs />; if (location.pathname === '/documents') return <Documents />; if (location.pathname === '/voice-intake') return <VoiceIntake />; if (location.pathname === '/ai-triage') return <AITriage />; if (location.pathname === '/followups') return <Followups />; if (location.pathname === '/ayush') return <Ayush />; if (location.pathname === '/schemes') return <Schemes />; return <Shell />; }
function BackControl() { const navigate = useNavigate(); if (location.pathname === '/dashboard') return null; const fallback = location.pathname.startsWith('/patients/') ? '/patients' : location.pathname === '/patient/card' ? '/patient' : '/dashboard'; return <button className="back-control" aria-label="Go back" title="Go back" onClick={() => { if (window.history.length > 1) navigate(-1); else navigate(fallback); }}>← Back</button>; }
function PatientCloseControl() { const navigate = useNavigate(); if (!location.pathname.startsWith('/patients')) return null; return <button className="patient-close-control" aria-label="Close patient view" title="Close patient view" onClick={() => navigate(location.pathname === '/patients' ? '/dashboard' : '/patients')}>×</button>; }
function AppWithBack() { const route = useLocation(); const isLogin = route.pathname === '/login' || !localStorage.getItem('niramay_token'); return isLogin ? <App key={route.pathname} /> : <><BackControl /><PatientCloseControl /><App key={route.pathname} /></>; }
createRoot(document.getElementById('root')!).render(<React.StrictMode><BrowserRouter><AppWithBack /></BrowserRouter></React.StrictMode>);
